CREATE TABLE IF NOT EXISTS agents (id TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'idle', current_task TEXT, heartbeat_at TEXT, metadata TEXT DEFAULT '{}');
CREATE TABLE IF NOT EXISTS tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS api_tokens (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, role TEXT NOT NULL DEFAULT 'tenant', status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL, last_used_at TEXT);
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, action TEXT NOT NULL, step TEXT NOT NULL, agent_id TEXT NOT NULL, status TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 50, input TEXT NOT NULL DEFAULT '{}', output TEXT DEFAULT '{}', attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, error TEXT, approval_granted INTEGER NOT NULL DEFAULT 0, workflow_id TEXT, max_steps INTEGER NOT NULL DEFAULT 30, max_retries INTEGER NOT NULL DEFAULT 3, compute_budget_usd REAL NOT NULL DEFAULT 0.25, max_output_tokens INTEGER NOT NULL DEFAULT 1200);
CREATE TABLE IF NOT EXISTS task_results (id TEXT PRIMARY KEY, task_id TEXT NOT NULL, tenant_id TEXT NOT NULL, step TEXT NOT NULL, result TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approvals (id TEXT PRIMARY KEY, task_id TEXT NOT NULL, tenant_id TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', step TEXT NOT NULL, created_at TEXT NOT NULL, resolved_at TEXT, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, ts TEXT NOT NULL, actor_id TEXT, actor_role TEXT, tenant_id TEXT, type TEXT NOT NULL, payload TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS system_controls (id INTEGER PRIMARY KEY CHECK(id=1), enabled INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS client_instances (id TEXT PRIMARY KEY, client_id TEXT NOT NULL, website_id TEXT, instance_type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', subscription_status TEXT NOT NULL DEFAULT 'inactive', config TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS website_connectors (id TEXT PRIMARY KEY, client_id TEXT NOT NULL, website_id TEXT NOT NULL, instance_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', public_key TEXT, secret_ref TEXT, allowed_origins TEXT NOT NULL DEFAULT '[]', consent_mode TEXT NOT NULL DEFAULT 'required', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS growth_audits (id TEXT PRIMARY KEY, client_id TEXT NOT NULL, website_id TEXT NOT NULL, audit_type TEXT NOT NULL, score REAL, findings TEXT NOT NULL DEFAULT '{}', evidence TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subscriptions (id TEXT PRIMARY KEY, client_id TEXT NOT NULL, product TEXT NOT NULL, status TEXT NOT NULL, amount TEXT, currency TEXT, interval TEXT, terms TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_tasks_tenant_status ON tasks(tenant_id,status,priority,created_at);
CREATE INDEX IF NOT EXISTS idx_results_tenant ON task_results(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS idx_approvals_tenant ON approvals(tenant_id,status,created_at);
CREATE INDEX IF NOT EXISTS idx_audit_tenant ON audit_log(tenant_id,ts DESC);
INSERT OR IGNORE INTO system_controls(id,enabled,updated_at) VALUES(1,1,datetime('now'));
